from datetime import datetime
from pydantic import BaseModel
from fastapi.encoders import jsonable_encoder

class Model(BaseModel):
    value: datetime

    class Config:
        json_encoders = {}

model = Model(value=datetime(2020, 1, 1))
jsonable_encoder(model, custom_encoder={datetime: lambda value: "temporary"})
assert jsonable_encoder(model) == {"value": "2020-01-01T00:00:00"}

from fastapi import FastAPI, Header, Query

app = FastAPI()

@app.get("/items")
def items(
    query_value: str = Query(..., alias="x"),
    header_value: str = Header(..., alias="x"),
):
    return None

parameters = app.openapi()["paths"]["/items"]["get"]["parameters"]
assert {(item["name"], item["in"]) for item in parameters} == {
    ("x", "query"),
    ("x", "header"),
}

from fastapi import APIRouter, FastAPI, Security
from fastapi.responses import JSONResponse
from fastapi.security import APIKeyHeader

callbacks = APIRouter(default_response_class=JSONResponse)
key = APIKeyHeader(name="X-Callback-Key")

@callbacks.post("/hook")
def hook(token: str = Security(key)):
    return {}

app = FastAPI()

@app.post("/subscribe", callbacks=callbacks.routes)
def subscribe():
    return {}

schema = app.openapi()
schemes = schema.get("components", {}).get("securitySchemes", {})
assert "APIKeyHeader" in schemes, schema
